/* Incremental CareFlow UI adapters. Existing screens and event handlers remain available. */
const CF=CareFlowCore;
const CF_OLD={initial,persist,render,appHeader,homeView,dashboard,queuePage,patientView,patientContent,timelineEvents,saveContact,showTask,saveTask,settingsPage,journeysPage,insightsPage,exportPatient,showNotifications,goto,openPatient,section,draftAssist};
const CF_KEY='careflow-workspace-v2';let cfStorageBlocked=false,cfRouting=false,cfShowcase=null;
try{const saved=localStorage.getItem(CF_KEY);S=CF.migrate(saved?JSON.parse(saved).state:S,DATA);if(!localStorage.getItem('careflow-recovery-v1')&&localStorage.getItem(KEY))localStorage.setItem('careflow-recovery-v1',localStorage.getItem(KEY));}catch(e){cfStorageBlocked=true;S=CF.migrate(S,DATA);storageAvailable=false;setTimeout(()=>toast('The saved v2 workspace could not be loaded. Original data is retained. Export a backup or explicitly reset to recover.'),200);}
initial=()=>CF.migrate(CF_OLD.initial(),DATA);
persist=function(){if(tour||cfShowcase)return;if(cfStorageBlocked){storageAvailable=false;return;}try{CF.validate(S,DATA);localStorage.setItem(CF_KEY,JSON.stringify({format:'careflow-workspace',schemaVersion:2,savedAt:new Date().toISOString(),state:S}));storageAvailable=true;}catch(e){storageAvailable=false;toast('Could not save this change. Your original saved data is retained. Export a backup before closing.');}};
function cfCommit(fn){const next=JSON.parse(JSON.stringify(S));const result=fn(next);CF.validate(next,DATA);S=next;persist();return result;}
function cfButton(action,text,id='',extra='',cls=''){return `<button type="button" class="btn ${cls}" data-cf="${action}" ${id?`data-member="${esc(id)}"`:''} ${extra}>${text}</button>`;}
function cfSelect(label,name,values,value){return `<label>${label}<select name="${name}" aria-label="${label}">${values.map(v=>`<option value="${esc(Array.isArray(v)?v[0]:v)}" ${(Array.isArray(v)?v[0]:v)===value?'selected':''}>${esc(Array.isArray(v)?v[1]:v)}</option>`).join('')}</select></label>`;}
function cfDate(v){if(!v)return 'Date unavailable';return new Date(v.length===10?v+'T12:00:00-05:00':v).toLocaleString('en-US',{month:'short',day:'numeric',...(v.length>10?{hour:'2-digit',minute:'2-digit'}:{}),timeZone:'America/New_York'});}
function cfMoneyLabel(){return 'Synthetic demo · no actual calls or messages';}
function cfFeedbackTask(){return S.tasks.find(t=>t.id===S.cf.feedbackTask);}
function cfHasReview(id){return CF.pendingCalls(S,id).length+CF.negative(S,id).length;}
function cfSourceButtons(refs,id){return refs.map(r=>cfButton('evidence',esc(typeof r==='string'?r:r.id)+' ↗',id,`data-record="${esc(typeof r==='string'?r:r.id)}"`,'quiet small')).join(' ');}
function cfRoute(){if(cfRouting)return;const h=location.hash.slice(1).split('/').map(decodeURIComponent);if(!h[0])return;cfRouting=true;try{if(h[0]==='feedback'&&S.tasks.some(t=>t.id===h[1])){S.active='home';S.view='feedback';S.cf.feedbackTask=h[1];}else if(h[0]==='member'&&patient(h[1])){if(!S.tabs.includes(h[1]))S.tabs.push(h[1]);S.active=h[1];S.patientSection[h[1]]=h[2]||'overview';}else if(h[0]==='home'&&['dashboard','queue','cases','tasks','insights','sources','journeys','exports','settings','audit'].includes(h[1])){S.active='home';S.view=h[1];}render();}finally{cfRouting=false;}}
function cfPush(){if(cfRouting||tour||cfShowcase)return;const route=S.active==='home'?(S.view==='feedback'?'feedback/'+encodeURIComponent(S.cf.feedbackTask):'home/'+S.view):'member/'+S.active+'/'+(S.patientSection[S.active]||'overview');if(location.hash.slice(1)!==route)history.pushState(null,'','#'+route);}
goto=function(view){CF_OLD.goto(view);cfPush();};openPatient=function(id){CF_OLD.openPatient(id);cfPush();};section=function(id,name){CF_OLD.section(id,name);cfPush();};window.addEventListener('popstate',cfRoute);window.addEventListener('hashchange',cfRoute);
effectiveTier=p=>CF.priority(S,DATA,p.id).tier;
overdue=t=>CF.isOverdue(S,t);sortedPatients=()=>CF.sorted(S,DATA);
reasonFor=p=>[CF.priority(S,DATA,p.id).reasons[0],nextActionLabel(p.id)];
function nextActionLabel(id){return CF.nextAction(S,DATA,id).label;}
filteredPatients=function(){let list=CF_OLD.initial?sortedPatients():[];const q=(S.filters.search||'').toLowerCase(),quick=S.cf.filters.quick||'all';list=list.filter(p=>(!q||`${p.name} ${p.id} CASE-${p.id} ${p.scenario}`.toLowerCase().includes(q))&&(S.filters.tier==='all'||effectiveTier(p)===S.filters.tier)&&(S.filters.status==='all'||S.cases[p.id].status===S.filters.status)&&(S.filters.program==='all'||p.plan.includes(S.filters.program)));list=list.filter(p=>{const ts=CF.tasks(S,p.id);switch(quick){case 'priority':return ['P0','P1'].includes(effectiveTier(p));case 'due':return ts.some(t=>t.due===CF.today(S));case 'overdue':return ts.some(t=>overdue(t));case 'waiting':return ts.some(t=>t.status==='Waiting external');case 'outreach':return S.cases[p.id].status==='Outreach';case 'review':return cfHasReview(p.id)>0;case 'changed':return CF.changes(S,DATA,p.id).length>0;default:return true;}});if(S.cf.filters.sort==='name')list.sort((a,b)=>pname(a).localeCompare(pname(b)));if(S.cf.filters.sort==='updated')list.sort((a,b)=>(CF.changes(S,DATA,b.id)[0]?.receivedAt||'').localeCompare(CF.changes(S,DATA,a.id)[0]?.receivedAt||''));return list;};
queueTable=function(list=filteredPatients()){return list.length?`<div class="table-wrap"><table class="queue-table cf-queue"><thead><tr><th>Member / case</th><th>Review priority</th><th>Why now / latest change</th><th>Next useful action</th><th class="optional">Review / owner</th><th class="when">Contact</th></tr></thead><tbody>${list.map(p=>{const pr=CF.priority(S,DATA,p.id),n=CF.nextAction(S,DATA,p.id),t=CF.tasks(S,p.id).sort((a,b)=>a.due.localeCompare(b.due))[0],ev=S.cf.events.find(e=>e.member===p.id);return `<tr><td><button class="patient-link" data-action="open" data-id="${p.id}" data-tour="open-${p.id}">${avatar(p)}<span><strong>${esc(pname(p))}</strong><small>${p.id} · ${esc(S.cases[p.id].status)}</small></span></button></td><td>${cfButton('priority',esc(pr.tier),p.id,'','small '+(pr.tier==='P1'?'cf-amber':''))}${pr.override?'<small class="cf-sub">RN override</small>':''}</td><td class="reason"><strong>${esc(pr.reasons[0])}</strong><span>${esc(ev?ev.title:p.scenario)}</span></td><td>${cfButton('next',esc(n.label),p.id,'','quiet small cf-wrap')}</td><td class="optional"><span>${t?cfDate(t.nextReviewAt||t.due):'Monitoring'}</span><small class="cf-sub">${esc(S.cases[p.id].owner)}</small></td><td class="when small muted">${bestTimes[p.id]}</td></tr>`;}).join('')}</tbody></table></div>`:empty('No cases match','Clear a filter or search to see more cases.');};
function cfQuick(){return `<div class="cf-filters" aria-label="Worklist quick filters">${[['all','All cases'],['priority','High priority'],['due','Due today'],['overdue','Overdue'],['waiting','Waiting on others'],['outreach','Needs outreach'],['review','Needs review'],['changed','Recently changed']].map(([v,l])=>cfButton('filter',l,'',`data-value="${v}" aria-pressed="${S.cf.filters.quick===v}"`,S.cf.filters.quick===v?'cf-selected small':'quiet small')).join('')}<label class="cf-sort">Sort <select aria-label="Worklist sorting" data-cf-change="sort"><option value="priority" ${S.cf.filters.sort==='priority'?'selected':''}>Priority and due date</option><option value="name" ${S.cf.filters.sort==='name'?'selected':''}>Member name</option><option value="updated" ${S.cf.filters.sort==='updated'?'selected':''}>Latest change</option></select></label></div>`;}
dashboard=function(){const ts=CF.tasks(S),active=DATA.patients.filter(p=>!isClosed(p)),calls=CF.pendingCalls(S),waiting=ts.filter(t=>t.status==='Waiting external');return `<div class="page-inner cf-command"><div class="page-head spread"><div><div class="eyebrow">RN command center · ${cfDate(CF.now(S))} ET</div><h1>Good morning, <span class="greeting-accent">Maria.</span></h1><p>Your next decision, with the context to make it.</p></div><div class="row">${cfButton('clock','Demo time')}${cfButton('inject','Simulate new alert','SYN-001')}${btn('nav','Full worklist','queue','','data-view="queue" data-tour="nav-queue"')}</div></div><div class="cf-metrics">${[[active.length,'Active cases','5 fictional members','all'],[active.filter(p=>['P0','P1'].includes(effectiveTier(p))).length,'Priority reviews','Not confirmed emergencies','priority'],[ts.filter(t=>t.due===CF.today(S)).length,'Due today','Owned commitments','due'],[ts.filter(overdue).length,'Overdue','Needs follow-through','overdue'],[calls.length,'AI reviews','Simulations awaiting review','review']].map(([n,l,c,f])=>`<button class="metric" data-cf="filter" data-value="${f}"><span class="metric-label">${l}</span><div class="num">${n.toString().padStart(2,'0')}</div><span class="caption">${c}</span></button>`).join('')}</div><div class="cf-section-head"><h2>Who needs you now</h2><span class="small muted">CareLens · Explainable review priority</span></div>${cfQuick()}${filters()}<div id="queue-results">${queueTable()}</div><div class="cf-bottom-grid"><section><div class="cf-section-head"><h2>Waiting on others</h2>${cfButton('waiting','All dependencies','','','quiet small')}</div>${waiting.length?waiting.slice(0,4).map(t=>cfPending(t)).join(''):empty('No external dependencies','New waiting actions will appear here.')}</section><section><div class="cf-section-head"><h2>CareOps AI</h2><span class="pill">Simulation</span></div><p class="muted small">Routine outreach, with explicit permission and human review.</p><div class="cf-mini-stats"><span><strong>${S.cf.calls.filter(c=>c.status==='Completed').length}</strong> completed simulations</span><span><strong>${calls.filter(c=>c.escalation).length}</strong> escalations to review</span><span><strong>${S.cf.feedback.length}</strong> patient reports</span></div>${calls.slice(0,2).map(c=>`<button class="cf-attention" data-cf="open-call" data-member="${c.member}" data-entity="${c.id}">${esc(pname(patient(c.member)))} · ${esc(c.escalation||'Call findings awaiting review')} →</button>`).join('')}<p class="tiny muted" style="margin-top:10px">Maria's 48-case workload is persona context, not a fabricated demo count.</p></section></div></div>`;};
queuePage=()=>`<div class="page-inner"><div class="page-head spread"><div><h1>Worklist</h1><p>Review priority, contact window and next action remain separate.</p></div>${btn('queue-policy','How priorities work','shield')}</div>${cfQuick()}${filters()}<div id="queue-results">${queueTable()}</div></div>`;
function cfPending(t){return `<button class="cf-pending" data-cf="action" data-member="${t.member}" data-entity="${t.id}"><div><strong>${esc(t.title)}</strong><small>${esc(pname(patient(t.member)))} · waiting for ${esc(t.externalParty||t.service||'external party not yet named')}</small><small>Accountable: ${esc(t.owner)} · review ${cfDate(t.nextReviewAt||t.due)}</small></div><span class="pill ${overdue(t)?'amber':''}">${overdue(t)?'Overdue':'Waiting external'}</span></button>`;}
function cfLens(p){const qs=S.cf.questions[p.id]||[],b=CF.baseline(S,p.id);return `<section class="cf-lens"><div class="cf-section-head"><div><span class="eyebrow">CareLens</span><h2>Ask about ${esc(pname(p).split(' ')[0])}</h2></div><span class="pill">Grounded · deterministic</span></div><form data-cf-form="question" data-member="${p.id}" class="cf-ask"><input name="question" id="cf-question-${p.id}" aria-label="Ask about ${esc(pname(p))}" placeholder="Ask anything about this member…" autocomplete="off" maxlength="500"><button type="submit" class="btn primary">Ask CareLens</button></form><div class="cf-suggestions">${['Why is this case high priority?','What medication discrepancies are recorded?','What changed since my last interaction?','What commitments remain unresolved?'].map(q=>cfButton('ask-example',esc(q),p.id,`data-question="${esc(q)}"`,'quiet small')).join('')}</div>${qs.length?qs.slice(-3).reverse().map(a=>`<article class="cf-answer" aria-live="polite"><strong>${esc(a.question)}</strong><p>${esc(a.text)}</p><div class="cf-citations">${cfSourceButtons(a.sources,p.id)}</div><small>${esc(a.mode)} · ${cfDate(a.at)} ET. Unknown information remains unknown.</small></article>`).join(''):''}<div class="cf-lens-footer"><span class="tiny muted">Last meaningful contact: ${b?cfDate(b.at)+' · '+b.label+(b.precision==='day'?' (date precision only)':''):'none recorded'}</span>${cfButton('section','Since your last interaction',p.id,'data-section="changes"','quiet small')}</div></section>`;}
function cfChanges(p){const b=CF.baseline(S,p.id),events=CF.changes(S,DATA,p.id),filter=S.cf.changeFilter||'all';return `<div class="cf-section-head"><div><span class="eyebrow">CareLens</span><h2>Since your last interaction</h2></div>${cfButton('inject','Receive earlier-event update',p.id,'','small')}</div><div class="notice-line">${b?'Compared with '+cfDate(b.at)+' · '+b.label+(b.precision==='day'?'. Same-day ordering is uncertain because the seed contains no exact contact time.':''):'No meaningful interaction is recorded. This is available context, not a claim of change since a conversation.'}</div><label class="cf-inline-label">Event category <select data-cf-change="change-filter" aria-label="Change category">${['all','AI activity','Patient feedback','Coordination','RN action','Clinical event'].map(v=>`<option ${filter===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="cf-timeline">${events.filter(e=>filter==='all'||e.type===filter).map(e=>`<article><div class="cf-event-dot"></div><div class="cf-section-head"><h3>${esc(e.title)}</h3><span class="pill">${esc(e.type)}</span></div>${e.late?'<span class="pill amber">Newly received information about an earlier event</span>':''}<p>${esc(e.detail)}</p><small>Occurred / observed: ${cfDate(e.eventAt)} · received: ${cfDate(e.receivedAt)}${e.precisionUnknown?' · same-day sequence unknown':''}</small><div>${cfSourceButtons(e.sourceRefs||[],p.id)}${e.entityId&&S.tasks.some(t=>t.id===e.entityId)?cfButton('action','Open action',p.id,`data-entity="${e.entityId}"`,'quiet small'):''}</div></article>`).join('')||empty('No changes in this category','The unresolved care plan remains available below.')}</div><h3>Still unresolved</h3>${taskLines(CF.tasks(S,p.id))}`;}
function cfCalls(p){const cs=S.cf.calls.filter(c=>c.member===p.id),c=cs.find(c=>c.id===S.cf.selectedCall)||cs.at(-1);return `<div class="cf-section-head"><div><span class="eyebrow">CareOps AI · simulated voice outreach</span><h2>Routine work, reviewed by you</h2></div>${cfButton('prepare-call','Prepare outreach',p.id,'','primary')}</div><p class="notice-line">No telephone connection is made. Scripts, participants and transcripts are fictional. No paid key is required.</p><div class="cf-call-history">${cs.map(c=>cfButton('open-call',cfDate(c.startedAt)+' · '+c.status,p.id,`data-entity="${c.id}"`,'small')).join('')}</div>${c?`<div class="cf-call"><div class="cf-section-head"><div><span class="pill ${c.escalation?'amber':''}">${esc(c.status)}</span><h3>${esc(c.language)} · ${esc(c.branch)} branch</h3><small>${esc(c.id)} · ${p.id} · ${c.caseId}</small></div><span class="cf-call-pulse ${c.status==='Running'?'running':''}" aria-label="${c.status==='Running'?'Simulation running':'Simulation stopped'}">◉</span></div><div class="cf-transcript" role="log" aria-label="Simulated conversation transcript">${c.turns.map(t=>`<div class="cf-turn ${t.speaker==='AI'?'ai':'member'}"><span>${esc(t.speaker||'System')} · script +${t.elapsed||0}s</span><p>${esc(t.text||'No response recorded')}</p><small>${esc(t.id)}</small></div>`).join('')||'<p class="muted">Ready for the first simulated response.</p>'}</div>${['Running','Paused'].includes(c.status)?`<div class="row wrap">${cfButton('call-step','Next response',p.id,`data-entity="${c.id}" ${c.status==='Paused'?'disabled':''}`,'primary')}${cfButton('call-pause',c.status==='Paused'?'Resume':'Pause',p.id,`data-entity="${c.id}"`)}${cfButton('call-end','End interaction',p.id,`data-entity="${c.id}"`)}${cfButton('call-human','Request human assistance',p.id,`data-entity="${c.id}"`)}</div>`:`<section class="cf-summary"><h3>Post-call summary</h3><p>${esc(c.summary)}</p>${c.escalation?`<div class="notice-line">${esc(c.escalation)}</div>`:''}<h4>Known before the call</h4><p>${esc(c.findings?.known)}</p><h4>Newly reported</h4>${(c.findings?.reported||[]).map(r=>`<p>${pill(r.state)} ${esc(r.text)} <small>${esc(r.source)}</small></p>`).join('')||'<p>No substantive member report collected.</p>'}<h4>Still unknown</h4><p>${esc(c.findings?.unknown.join('; '))}</p><div class="row">${c.reviewState==='Reviewed'?pill('Reviewed by RN','green'):cfButton('review-call','Review findings and proposed actions',p.id,`data-entity="${c.id}"`,'primary')}</div></section>`}</div>`:empty('No AI interactions yet','Prepare a permitted route and choose a simulation branch. Manual outreach remains available.')}`;}
function cfOutcomeFor(p){const goals=S.cf.goals.filter(g=>g.member===p.id),ts=S.tasks.filter(t=>t.member===p.id);return `<div class="cf-section-head"><div><span class="eyebrow">CareMesh + OutcomeLoop</span><h2>Support received. Need addressed?</h2></div>${cfButton('new-goal','Add goal',p.id)}</div><p class="notice-line">An action completed, a service delivered and a patient goal achieved are separate facts. Patient reports retain their verification status.</p>${goals.map(g=>`<section class="cf-goal"><div class="cf-section-head"><h3>${esc(g.statement)}</h3>${pill(g.status,g.status==='Achieved'?'green':g.status==='Blocked'?'amber':'')}</div><p class="muted small">Success criteria: ${esc(g.criteria)}</p><p class="small">Barrier: ${esc(g.barrier||'None newly established')}</p><div class="row">${cfButton('goal','Review progress',p.id,`data-entity="${g.id}"`,'small')}<span class="tiny muted">${g.history.length} recorded updates · ${g.evidence.length} evidence entries</span></div>${g.history.slice(-3).map(h=>`<p class="tiny muted">${cfDate(h.at)} · ${esc(h.detail)}</p>`).join('')}</section>`).join('')}<h3 style="margin-top:24px">Interventions and follow-through</h3>${ts.map(t=>cfActionCard(t)).join('')}`;}
function cfActionCard(t){const f=CF.latestFeedback(S,t),pending=t.status==='Waiting external';return `<article class="cf-action-card ${overdue(t)?'overdue':''}" id="cf-action-${esc(t.id)}"><div class="cf-section-head"><button data-cf="action" data-member="${t.member}" data-entity="${t.id}"><h3>${esc(t.title)}</h3></button>${pill(t.status,overdue(t)?'amber':t.status==='Completed'?'green':'')}</div><small>${esc(t.id)} · ${esc(pname(patient(t.member)))} · ${t.caseId}</small><div class="cf-action-meta"><span>Accountable <strong>${esc(t.owner)}</strong></span><span>Due <strong>${cfDate(t.due)}</strong></span><span>Review <strong>${cfDate(t.nextReviewAt||t.due)}</strong></span></div>${pending?`<p class="small">Waiting for: <strong>${esc(t.externalParty||t.service||'external party not yet named')}</strong> · ${t.waitingSince?'since '+cfDate(t.waitingSince):'waiting start time unavailable in legacy record'}</p>`:''}<div class="cf-outcome-line"><span>Action ${pill(t.status)}</span><span>Service ${pill(t.type==='Referral'?t.referral:'No delivery established')}</span><span>Benefit ${pill(t.outcome?.status||'Unknown',f?.followUpRequired?'amber':'')}</span></div><p class="tiny muted">${esc(t.outcome?.verification||'Not verified')} · ${(t.evidenceEntries||[]).length} dated evidence entries · ${(t.dependencies||[]).length} dependencies</p>${f?`<blockquote class="cf-feedback-quote">${esc(f.comments||f.response)}<small>${esc(f.submittedBy)} · ${cfDate(f.submittedAt)} · ${esc(f.verificationStatus)}</small></blockquote>`:'<p class="small muted">No patient feedback yet. Outcome remains unknown.</p>'}<div class="row wrap">${cfButton('action','Review action',t.member,`data-entity="${t.id}"`,'small')}${cfButton('feedback-open','Open patient feedback',t.member,`data-entity="${t.id}"`,'quiet small')}</div></article>`;}
tasksPage=function(){const f=S.cf.actionFilter||'all';let ts=S.tasks;if(f==='waiting')ts=ts.filter(t=>t.status==='Waiting external');if(f==='overdue')ts=ts.filter(overdue);if(f==='unresolved')ts=ts.filter(t=>CF.latestFeedback(S,t)?.followUpRequired);if(f==='open')ts=ts.filter(CF.open);if(f==='completed')ts=ts.filter(t=>t.status==='Completed');return `<div class="page-inner"><div class="page-head spread"><div><div class="eyebrow">CareMesh + OutcomeLoop</div><h1>Actions & outcomes</h1><p>Every dependency has an owner. Every outcome keeps its evidence.</p></div><div class="row">${btn('export-tasks','Export CSV','download')}${btn('new-task','Add action','plus','primary')}</div></div><div class="cf-filters">${[['all','All actions'],['open','Open'],['waiting','Waiting on others'],['overdue','Overdue'],['unresolved','Unresolved feedback'],['completed','Completed']].map(([v,l])=>cfButton('action-filter',l,'',`data-value="${v}" aria-pressed="${f===v}"`,f===v?'small cf-selected':'quiet small')).join('')}</div>${f==='waiting'?'<p class="notice-line">Waiting on others: an external response never removes internal accountability. Last response and next review remain visible in the action.</p>':''}${ts.map(cfActionCard).join('')||empty('No actions in this view','Change the filter or create an action.')}</div>`;};
patientContent=function(p,sect){if(sect==='changes')return cfChanges(p);if(sect==='calls')return cfCalls(p);if(sect==='outcomes')return cfOutcomeFor(p);return (sect==='overview'?cfLens(p):'')+CF_OLD.patientContent({...p,action:nextActionLabel(p.id)},sect);};
patientView=function(p){let html=CF_OLD.patientView(p);html=html.replace('<div class="patient-toolbar">','<div class="patient-toolbar">'+cfButton('prepare-call','AI outreach',p.id,'','cf-ai-button'));const nav=['changes','calls','outcomes'].map((v,i)=>`<button data-cf="section" data-member="${p.id}" data-section="${v}" class="${S.patientSection[p.id]===v?'active':''}">${['Since last interaction','AI outreach','Goals & outcomes'][i]}</button>`).join('');html=html.replace('</nav></header>',nav+'</nav></header>');return html;};
timelineEvents=function(p){let es=CF_OLD.timelineEvents(p).filter(e=>!e.title.startsWith('Note signed')&&!e.title.endsWith(' · completed'));es.push(...S.notes.filter(n=>n.member===p.id).map(n=>({at:n.simulatedAt||n.signedAt,type:'Clinical',title:'Signed note · '+n.author,desc:n.text,icon:'file'})));es.push(...S.cf.events.filter(e=>e.member===p.id).map(e=>({at:e.eventAt||e.at,type:e.type,title:e.title,desc:e.detail+' · recorded '+cfDate(e.receivedAt),icon:e.type==='Patient feedback'?'heart':'task'})));return es.sort((a,b)=>String(b.at).localeCompare(String(a.at)));};
function cfFeedbackPage(){const t=cfFeedbackTask();if(!t)return `<div class="cf-feedback-shell"><h1>Feedback link unavailable</h1><p>Choose a valid fictional intervention.</p>${cfButton('return-rn','Return to workspace')}</div>`;const p=patient(t.member),confirmation=S.cf.feedbackConfirmation;return `<div class="cf-feedback-shell"><div class="cf-feedback-brand">${I('heart')} CareFlow</div><span class="pill">Fictional patient feedback · same-browser demo</span><h1>Hello, ${esc(pname(p).split(' ')[0])}.</h1><p class="cf-feedback-sub">${esc(t.title)}</p>${confirmation?.task===t.id?`<section role="status"><h2>Your update is saved.</h2><p>It is recorded as ${esc(confirmation.by==='Patient'?'patient':'caregiver')}-reported information. Your care manager's workspace now reflects this update.</p>${cfButton('return-rn','See Maria’s updated workspace',t.member,'','primary')}${cfButton('feedback-another','Submit a later update',t.member,'','quiet')}</section>`:`<form id="cf-feedback-form" data-task="${esc(t.id)}"><h2>Did this support help with your goal?</h2>${[['helped','Yes, it helped'],['partly','It partly helped'],['help','No, I still need help'],['not-received',"I didn’t receive the service"],['person','I prefer to speak to my care manager']].map(([v,l])=>`<label class="cf-feedback-option"><input type="radio" name="response" value="${v}"><span>${l}</span></label>`).join('')}<label>Anything you’d like us to know? <span class="muted">(optional)</span><textarea name="comments" maxlength="2000" placeholder="Tell us what happened…"></textarea></label>${cfSelect('Who is responding?','respondent',t.member==='SYN-005'?['Patient','Authorized caregiver']:['Patient'],'Patient')}<p class="tiny muted">Caregiver authority covers coordination only. This demo does not send a message or connect separate devices.</p><div id="cf-feedback-error" role="alert"></div><button type="submit" class="btn primary">Send update</button></form>`}<footer>${cfButton('return-rn','RN workspace',t.member,'','quiet small')}<span>Synthetic data only. No real patient information.</span></footer></div>`;}
homeView=function(){return S.view==='feedback'?cfFeedbackPage():CF_OLD.homeView();};appHeader=function(){return S.active==='home'&&S.view==='feedback'?cfFeedbackPage():CF_OLD.appHeader();};
render=function(){if(!S.cf)S=CF.migrate(S,DATA);CF_OLD.render();for(const [v,l]of [['dashboard','Command Center'],['cases','My cases'],['tasks','Actions & outcomes']]){const b=document.querySelector(`.sidebar [data-view="${v}"]`);if(b){const label=b.querySelector('.nav-label');if(label)label.textContent=l;b.setAttribute('aria-label',l);}}
 const clock=$('.statusbar .row:last-child > span');if(clock)clock.textContent=cfDate(CF.now(S))+' ET · demo time';
 document.querySelectorAll('[data-tab]').forEach(el=>{const id=el.dataset.tab;el.querySelectorAll('.badge-count').forEach(x=>x.remove());const n=cfHasReview(id);if(n){const span=document.createElement('span');span.className='badge-count';span.textContent=String(n);span.title='Items requiring review';el.querySelector('[role=tab]')?.append(span);}});
 document.querySelectorAll('.timeline-item h4').forEach(h=>{if(h.textContent==='Reported not delivered')h.dataset.cfFeedbackEntry='true';});if(cfShowcase)cfShowcaseOverlay();cfIntro();};
audit=function(action,id='',detail=''){if(!S.cf)S=CF.migrate(S,DATA);CF.log(S,'RN action',id,action,detail);persist();};
saveContact=function(id){const ok=CF_OLD.saveContact(id);if(ok){const c=S.contacts.find(c=>c.member===id);if(c){c.attemptedAt=CF.now(S);c.interactionEventSequence=S.cf.sequence;}persist();render();}return ok;};
showTask=function(id,tid){CF_OLD.showTask(id,tid);const f=$('#task-form'),t=S.tasks.find(t=>t.id===tid);f.insertAdjacentHTML('beforeend',`<div class="form-grid cf-extra-fields">${field('Separate next review date','nextReviewAt',t?.nextReviewAt||t?.due||CF.today(S),'date')}${field('Evidence date','evidenceDate','','date')}${field('Evidence source / confirmer','evidenceSource','','text','Required for completed or verified service outcomes. Do not invent evidence.')}</div>`);};
saveTask=function(){const f=$('#task-form'),v=Object.fromEntries(new FormData(f)),old=S.tasks.find(t=>t.id===f.dataset.task);if(old){try{CF.updateTask(JSON.parse(JSON.stringify(S)),DATA,old.id,{...old,...v,externalParty:v.service||old.externalParty,dependencies:old.dependencies,nextReviewAt:v.nextReviewAt});}catch(e){return formError(e.message);}}else if(['Completed'].includes(v.status)&&(!v.evidenceDate||!v.evidenceSource?.trim()))return formError('New completed actions need dated, attributable evidence.');const ok=CF_OLD.saveTask();if(ok){S=CF.migrate(S,DATA);const t=old?S.tasks.find(t=>t.id===old.id):S.tasks.at(-1);t.nextReviewAt=v.nextReviewAt||v.due;t.externalParty=v.service||t.externalParty;if(v.evidenceDate&&v.evidenceSource?.trim())t.evidenceEntries.push({at:v.evidenceDate,source:v.evidenceSource,text:v.evidence,verification:'RN-recorded source'});persist();render();}return ok;};
function cfEvidence(id,rid){const r=CF.sourceRecords(DATA,id).find(r=>r.id===rid);const local=S.tasks.find(t=>t.id===rid&&t.member===id)||S.cf.events.find(e=>e.id===rid)||S.contacts.find(c=>c.id===rid)||S.cf.feedback.find(f=>f.id===rid)||S.cf.alerts.find(a=>a.id===rid);const c=S.cf.calls.find(c=>c.member===id&&c.turns.some(t=>t.id===rid));const turn=c?.turns.find(t=>t.id===rid);if(!r&&!local&&!turn)return toast('This evidence reference has no original source row. Review the linked member record.');showModal('Evidence · '+esc(rid),pname(patient(id))+' · '+id,`<div class="notice-line">Original evidence is preserved. An interpretation does not replace its source.</div>${r?`<p class="small"><strong>${esc(r.dataset)}</strong> · ${esc(r.source)}</p><dl class="cf-evidence-dl">${Object.entries(r.original).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v??'Unknown / unavailable')}</dd>`).join('')}</dl><p class="small muted">${esc(r.limitation)}</p>`:`<pre class="cf-pre">${esc(JSON.stringify(turn||local,null,2))}</pre>`}`,btn('close-modal','Close evidence'));}
function cfPrepare(id){const r=CF.readiness(S,DATA,id),c=S.cf.consents[id];showModal('Prepare simulated AI outreach',pname(patient(id))+' · '+id,`<p class="notice-line">Simulation only. No telephone connection or external message. Permission must be appropriate to recipient, purpose and channel.</p><div class="cf-readiness"><strong>${esc(r.contact)}</strong><span>${esc(r.language)} · preferred ${r.window} ET</span><p>${esc(patient(id).action)}</p></div>${r.errors.map(e=>`<p class="cf-warning">${esc(e)}</p>`).join('')}<form id="cf-call-form" data-member="${id}"><div class="form-grid">${cfSelect('Simulation branch','branch',[['barrier','Practical barrier'],['routine','Routine contact'],['person','Requests a nurse'],['clinical','Clinical concern / protocol escalation'],['unreachable','No answer']],'barrier')}${cfSelect('Script language','language',['English','Spanish'],patient(id).language)}</div><label class="checkline"><input name="ai" type="checkbox" ${c.ai?'checked':''}> I reviewed fictional AI-specific outreach permission for this purpose.</label><label class="checkline"><input name="channel" type="checkbox" ${c.channel?'checked':''}> This selected telephone channel is permitted.</label><label class="checkline"><input name="identity" type="checkbox" ${c.identity?'checked':''}> Recipient identity and the recorded route are verified for this simulation.</label>${id==='SYN-005'?`<label class="checkline"><input name="caregiver" type="checkbox" ${c.caregiver?'checked':''}> Daughter’s coordination scope and Dec 31 expiry reviewed.</label>`:''}<label class="checkline"><input name="optOut" type="checkbox" ${c.optOut?'checked':''}> Member has opted out of AI outreach (blocks simulation).</label><p class="small muted">Approved routine script: confirm purpose, collect practical coordination information, preserve unknowns, and stop for a person request or clinical concern. Clinical escalation follows a qualified protocol; this app does not diagnose.</p><div id="cf-call-error" role="alert"></div></form>`,`${cfButton('clock','Review / advance demo time',id)}${btn('close-modal','Cancel')}${cfButton('start-call','Start simulation',id,'','primary')}`,true);}
function cfReviewCall(id,cid){const c=S.cf.calls.find(c=>c.id===cid&&c.member===id);if(!c)return;showModal('Review simulated conversation',pname(patient(id))+' · '+id,`<div class="notice-line">Only observed transcript content may become reported information. Review the proposal before it changes the care plan.</div><p class="cf-pre">${esc(c.summary)}</p><h3>Unknown or unverified</h3><p>${esc(c.findings.unknown.join('; '))}</p><form id="cf-review-form"><label>Proposed action<input name="action" value="${esc(c.findings.proposed)}"></label><label class="checkline"><input type="checkbox" name="task" checked> Create an owned follow-up task</label><label class="checkline"><input type="checkbox" name="note" checked> Append a reviewable note draft (preserve existing draft)</label><label class="checkline"><input type="checkbox" name="reviewed"> I reviewed the facts, uncertainty and correct member context.</label><div id="cf-review-error" role="alert"></div></form>`,`${cfButton('reject-call','Reject proposal',id,`data-entity="${cid}"`)}${cfButton('approve-call','Approve selected updates',id,`data-entity="${cid}"`,'primary')}`,true);}
function cfActionModal(tid){const t=S.tasks.find(t=>t.id===tid);if(!t)return;showModal('Action and outcome',pname(patient(t.member))+' · '+t.caseId,`<p class="notice-line">Work completion, service receipt and patient benefit are separate. Completion needs dated, attributable evidence.</p><form id="cf-action-form" data-task="${t.id}"><div class="form-grid">${field('Action','title',t.title)}${field('Internal accountable owner','owner',t.owner)}${field('External party / service','externalParty',t.externalParty||t.service||'')}${field('Due date','due',t.due,'date')}${field('Next review date','nextReviewAt',t.nextReviewAt||t.due,'date')}${cfSelect('Work status','status',['Open','In progress','Waiting external','Completed','Cancelled'],t.status)}${cfSelect('Referral / service stage','referral',['Requested','Accepted','Scheduled','Service received','Verified','Unavailable','Declined'],t.referral||'Requested')}${field('Response or outcome evidence','evidence',t.evidence||'','textarea')}${field('Evidence date','evidenceDate','','date')}${field('Source / person confirming','evidenceSource','')}${cfSelect('Evidence classification','verification',['Patient-reported','Caregiver-reported','Provider-confirmed','RN-verified'],'Provider-confirmed')}</div><h4>Depends on</h4>${S.tasks.filter(x=>x.member===t.member&&x.id!==t.id).map(x=>`<label class="checkline"><input type="checkbox" name="dependencies" value="${x.id}" ${t.dependencies.includes(x.id)?'checked':''}>${esc(x.title)}</label>`).join('')||'<p class="small muted">No other actions for this member.</p>'}<div id="cf-action-error" role="alert"></div></form><h4>Last external response / evidence</h4><p class="small">${esc(t.evidence||'No response recorded.')}</p><h4>Activity history</h4>${t.history.slice(-5).map(h=>`<p class="small">${cfDate(h.at)} · ${esc(h.detail)}</p>`).join('')||'<p class="small muted">Historical transition times unavailable. New updates will be recorded.</p>'}<div class="row wrap" style="margin-top:12px">${cfButton('feedback-open','Patient feedback',t.member,`data-entity="${t.id}"`,'small')}${cfButton('substitute','Create substitute action',t.member,`data-entity="${t.id}"`,'quiet small')}${cfButton('escalate','Escalate for RN review',t.member,`data-entity="${t.id}"`,'quiet small')}</div>`,`${btn('close-modal','Cancel')}${cfButton('save-action','Save action',t.member,`data-entity="${t.id}"`,'primary')}`,true);}
function cfGoalModal(gid){const g=S.cf.goals.find(g=>g.id===gid);showModal('Review patient goal',pname(patient(g.member)),`<h3>${esc(g.statement)}</h3><form id="cf-goal-form">${cfSelect('Progress status','status',['Not started','In progress','Partially achieved','Achieved','Blocked','Unable to verify','Discontinued / transferred'],g.status)}${field('Agreed success criteria','criteria',g.criteria,'textarea')}${field('Supporting evidence or reason','evidence','','textarea')}<p class="small muted">A positive patient report does not independently verify every aspect of this goal.</p></form>`,`${btn('close-modal','Cancel')}${cfButton('save-goal','Save reviewed progress',g.member,`data-entity="${g.id}"`,'primary')}`);}
function cfClock(id=''){showModal('Demonstration time','Explicit simulation clock; no real appointment or call is scheduled.',`<p class="notice-line">Current demo time: ${cfDate(CF.now(S))} ET. Advancing time updates contact eligibility and due work. Event occurrence and receipt remain distinct.</p><form id="cf-clock-form"><label>Demo date and time<input type="datetime-local" name="time" value="${CF.now(S).slice(0,16)}" min="${CF.now(S).slice(0,16)}"></label><div id="cf-clock-error" role="alert"></div></form><div class="row wrap" style="margin-top:16px">${[['14:00','Morgan window'],['16:00','Casey window'],['17:30','Jordan window']].map(([time,label])=>cfButton('clock-preset',label,id,`data-value="${time}"`,'small')).join('')}</div>`,`${btn('close-modal','Cancel')}${cfButton('save-clock','Advance demo clock',id,'','primary')}`);}
notifications=function(){return DATA.patients.filter(p=>!isClosed(p)||cfHasReview(p.id)).map(p=>({id:p.id,member:p.id,title:CF.priority(S,DATA,p.id).reasons[0],detail:nextActionLabel(p.id),read:S.readNotifications.includes(p.id)})).filter(n=>!S.snoozed.includes(n.id));};
showNotifications=function(){const items=notifications();showModal('Attention and updates','Reading an item does not complete the work.',items.map(n=>`<div class="cf-notification"><strong>${esc(pname(patient(n.member)))}</strong><p>${esc(n.title)}</p><small>${esc(n.detail)}</small><div>${cfButton('notify-open','Open member',n.member,'','small')}${btn('notification-read',n.read?'Mark unread':'Mark read','','quiet small',`data-id="${n.member}"`)}${btn('notification-snooze','Snooze','','quiet small',`data-id="${n.member}"`)}</div></div>`).join('')||empty('No current attention items','Review the command center for all cases.'),`${btn('restore-notifications','Restore snoozed')}${btn('close-modal','Close')}`);};
settingsPage=()=>CF_OLD.settingsPage()+`<div class="page-inner cf-settings-extra"><h2>Upgrade data and demo controls</h2><p class="small muted">Version 2 migration preserves legacy records. Reset restores fictional seeds; backup/restore includes calls, feedback and goals.</p><div class="row">${cfButton('clock','Change demo time')}${cfButton('export-v2','Download complete v2 backup')}${cfButton('manual-limits','Simulation and storage limits')}</div></div>`;
journeysPage=()=>CF_OLD.journeysPage();
insightsPage=()=>`<div class="page-inner"><div class="page-head"><h1>Outcomes and AI activity</h1><p>Actual synthetic state. A report of benefit is distinct from independent verification.</p></div><div class="cf-metrics">${[[S.cf.feedback.length,'Feedback reports'],[S.cf.calls.length,'AI simulations'],[CF.pendingCalls(S).length,'Awaiting RN review'],[S.tasks.filter(t=>CF.latestFeedback(S,t)?.followUpRequired).length,'Reported unmet needs']].map(([n,l])=>`<div class="metric"><span class="metric-label">${l}</span><div class="num">${n}</div></div>`).join('')}</div><p class="notice-line">${S.cf.feedback.length} reports / ${S.tasks.filter(t=>!t.parentInterventionId).length} recorded interventions. This is not a response rate: no real feedback invitations were sent. Clinical effectiveness, fairness and escalation accuracy are not measured by this demo.</p>${CF_OLD.insightsPage()}</div>`;
exportPatient=function(id){exportBlob('CareFlow_'+id+'_complete.json',JSON.stringify({synthetic:true,schemaVersion:2,asOf:CF.now(S),member:patient(id),case:S.cases[id],tasks:S.tasks.filter(t=>t.member===id),contacts:S.contacts.filter(c=>c.member===id),draft:draftFor(id),notes:S.notes.filter(n=>n.member===id),goals:S.cf.goals.filter(g=>g.member===id),calls:S.cf.calls.filter(c=>c.member===id),feedback:S.cf.feedback.filter(f=>f.member===id),events:S.cf.events.filter(e=>e.member===id),sources:CF.sourceRecords(DATA,id)},null,2));};
function cfShowcaseStart(){
 if(tour)endJourney(false);if(cfShowcase)cfStoryStop();cfDismissIntro();closeModal();drawer=null;
 cfShowcase={snapshot:JSON.parse(JSON.stringify(S)),step:0};const theme=S.theme;S=initial();S.theme=theme;S.cf.clock='2026-11-09T14:00:00-05:00';S.active='home';S.view='dashboard';render();
}
const cfStoryMember='SYN-004';
function cfStoryCall(){return S.cf.calls.filter(c=>c.member===cfStoryMember).at(-1);}
// Each step activates an actual UI control. Next follows the identical event path.
const cfStory=[
 {title:'Open Morgan’s case',text:'Start with the overdue housing commitment. Open the highlighted patient row, or choose Next.',selector:'[data-tour="open-SYN-004"]',done:()=>S.active===cfStoryMember},
 {title:'Ask about unresolved commitments',text:'CareLens answers from this member’s evidence. Its citations let you inspect the original records.',selector:'[data-cf="ask-example"][data-question="What commitments remain unresolved?"]',done:()=>(S.cf.questions[cfStoryMember]||[]).length>0},
 {title:'Compare with the last interaction',text:'Open the change view. A failed contact never becomes a successful assessment.',selector:'[data-cf="section"][data-section="changes"]',done:()=>S.patientSection[cfStoryMember]==='changes'},
 {title:'Receive an earlier-event update',text:'This fictional provider response arrives now, but describes an earlier event. Occurrence and receipt times stay separate.',selector:'[data-cf="inject"][data-member="SYN-004"]',done:()=>S.cf.alerts.some(a=>a.member===cfStoryMember)},
 {title:'Prepare simulated outreach',text:'The demo is at Morgan’s preferred 14:00 contact time. No real call will be placed.',selector:'.patient-toolbar [data-cf="prepare-call"]',done:()=>!!$('#cf-call-form')},
 {title:'Review AI-specific permission',text:'This is a fictional walkthrough. Review the purpose-specific permission before checking this box; program enrollment alone is insufficient.',selector:'#cf-call-form [name="ai"]',done:()=>!!$('#cf-call-form [name="ai"]')?.checked},
 {title:'Confirm the permitted channel',text:'The telephone channel must be appropriate for the agreed coordination purpose.',selector:'#cf-call-form [name="channel"]',done:()=>!!$('#cf-call-form [name="channel"]')?.checked},
 {title:'Verify recipient and route',text:'Confirm the fictional recipient identity and recorded route. These checks remain required outside the walkthrough.',selector:'#cf-call-form [name="identity"]',done:()=>!!$('#cf-call-form [name="identity"]')?.checked},
 {title:'Start the fictional conversation',text:'Play the practical-barrier branch. It collects a reported need, not an independently verified service outcome.',selector:'[data-cf="start-call"]',done:()=>!!cfStoryCall()},
 ...[1,2,3,4].map((turn)=>({title:['Confirm the conversation purpose','Hear the member’s agreement','Hear what remains unresolved','Explain the proposed follow-up'][turn-1],text:['Read the simulated assistant’s opening. Use Next response, or Next here, to play this turn.','The member agrees to this coordination purpose. Consent does not establish that a service was delivered.','Morgan reports housing support has not arrived and transport is needed. Preserve this as patient-reported information.','The assistant proposes nurse review. No service is booked and no clinical assessment is invented.'][turn-1],selector:'[data-cf="call-step"]',done:()=>cfStoryCall()?.position>=turn})),
 {title:'Review the findings',text:'Read what is known, newly reported and still unknown before applying proposed updates.',selector:'[data-cf="review-call"]',done:()=>!!$('#cf-review-form')},
 {title:'Confirm your review',text:'Check the member identity, reported facts, uncertainty and proposed follow-up. The note remains unsigned.',selector:'#cf-review-form [name="reviewed"]',done:()=>!!$('#cf-review-form [name="reviewed"]')?.checked},
 {title:'Approve the selected updates',text:'Apply one owned follow-up and append a draft. Existing drafts are preserved; approval is not a signature.',selector:'[data-cf="approve-call"]',done:()=>cfStoryCall()?.reviewState==='Reviewed'},
 {title:'Open actions and outcomes',text:'See the coordination work created by this review alongside the existing housing intervention.',selector:'.sidebar [data-view="tasks"]',done:()=>S.active==='home'&&S.view==='tasks'},
 {title:'Find work waiting on others',text:'An agency dependency keeps an internal accountable owner and review date.',selector:'[data-cf="action-filter"][data-value="waiting"]',done:()=>S.cf.actionFilter==='waiting'},
 {title:'Ask whether support arrived',text:'Open feedback for Morgan’s housing intervention. It is linked to this specific action and member.',selector:'[data-cf="feedback-open"][data-entity="TASK-4"]',done:()=>S.view==='feedback'&&S.cf.feedbackTask==='TASK-4'},
 {title:'Report that the service did not arrive',text:'Use the fictional patient response. This is a reported outcome, not independent verification.',selector:'#cf-feedback-form [name="response"][value="not-received"]',done:()=>!!$('#cf-feedback-form [name="response"][value="not-received"]')?.checked},
 {title:'Save the patient’s report',text:'The report will renew attention and create one linked follow-up. It does not erase the original action or its history.',selector:'#cf-feedback-form button[type="submit"]',done:()=>S.cf.feedback.some(f=>f.member===cfStoryMember)},
 {title:'Return to Maria’s workspace',text:'The patient update and the nurse’s view share the same intervention, goal and evidence history.',selector:'.cf-feedback-shell [data-cf="return-rn"]',done:()=>S.active===cfStoryMember&&S.patientSection[cfStoryMember]==='outcomes'},
 {title:'Read the goal update',text:'The goal is blocked because support was reported not delivered. Click the highlighted goal or Next to continue. A completed action, service delivery and patient benefit remain separate.',selector:'.cf-goal h3',read:true},
 {title:'Check the shared timeline',text:'The feedback and nurse-reviewed changes also appear in the patient’s chronological record.',selector:'.patient-nav [data-action="section"][data-section="timeline"]',done:()=>S.patientSection[cfStoryMember]==='timeline'},
 {title:'The need remains open',text:'Review the patient feedback in the timeline. Next finishes this walkthrough and restores your original workspace.',selector:'[data-cf-feedback-entry]',read:true}
];
function cfStoryReady(){const st=cfShowcase&&cfStory[cfShowcase.step];return !!(st&&(st.read||st.done?.()));}
function cfShowcaseOverlay(scroll=false){
 if(!cfShowcase)return;document.documentElement.classList.add('cf-guiding');let host=$('#cf-story');if(!host){host=document.createElement('div');host.id='cf-story';document.body.append(host);}const st=cfStory[cfShowcase.step];
 if(host.dataset.step!==String(cfShowcase.step)){host.dataset.step=String(cfShowcase.step);host.innerHTML=`<div class="cf-guide-ring" aria-hidden="true"></div><aside class="cf-guide-pop" role="region" aria-label="Closed-loop journey prompt"><div class="spread"><span class="eyebrow">Closed-loop journey · ${cfShowcase.step+1} / ${cfStory.length}</span><button class="iconbtn" data-cf="story-exit" aria-label="Exit closed-loop journey">${I('close')}</button></div><h3>${esc(st.title)}</h3><p>${esc(st.text)}</p><div class="tour-progress">${cfStory.map((_,i)=>`<span class="${i<=cfShowcase.step?'done':''}"></span>`).join('')}</div><div class="tour-actions"><span class="tiny muted">Click the highlight, or let Next do it.</span>${cfButton('story-next','Next','','','primary small')}</div><small class="cf-guide-footnote">Fictional walkthrough · original workspace restores on exit</small></aside>`;scroll=true;}
 const target=$(st.selector);if(st.read&&target){target.dataset.cfTourRead='true';target.setAttribute('role','button');target.setAttribute('tabindex','0');target.setAttribute('aria-label','Read this summary and continue');}
 placeGuide(host,target,scroll);
}
function cfStoryAdvance(index){if(!cfShowcase||cfShowcase.step!==index)return;$$('[data-cf-tour-read]').forEach(el=>{delete el.dataset.cfTourRead;el.removeAttribute('role');el.removeAttribute('tabindex');el.removeAttribute('aria-label');});cfShowcase.step++;if(cfShowcase.step===cfStory.length){cfStoryStop();showModal('Journey complete','Your original workspace has been restored.','<div class="journey-complete"><h2>The loop stays connected.</h2><p>You reviewed evidence, simulated outreach, owned follow-up and the patient’s outcome without assuming the need was resolved.</p></div>',btn('close-modal','Return to workspace'));return;}cfShowcaseOverlay(true);}
function cfStoryNext(){if(!cfShowcase)return;const i=cfShowcase.step,st=cfStory[i];if(cfStoryReady()){cfStoryAdvance(i);return;}const target=$(st.selector);if(target)target.click();else toast('The current control is unavailable. Close any unrelated dialog or exit and replay this walkthrough.');}
function cfStoryStop(){if(!cfShowcase)return;S=cfShowcase.snapshot;cfShowcase=null;$('#cf-story')?.remove();modal=null;drawer=null;persist();render();toast('Original workspace restored.');}
// Capture the highlighted control before rendering replaces it, then advance
// after the existing validated action handlers have run. Submit follows its own event.
function cfStoryMark(e){if(!cfShowcase)return;const i=cfShowcase.step,target=$(cfStory[i].selector);if(target&&(target.contains(e.target)||e.type==='submit'&&e.target.contains(target)))e.cfJourneyStep=i;}
function cfStoryObserve(e){if(e.cfJourneyStep!=null&&cfShowcase?.step===e.cfJourneyStep&&cfStoryReady())cfStoryAdvance(e.cfJourneyStep);}
document.addEventListener('click',cfStoryMark,true);document.addEventListener('submit',cfStoryMark,true);
document.addEventListener('keydown',e=>{if(cfShowcase&&e.target.matches('[data-cf-tour-read]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click();}});

document.addEventListener('submit',e=>{const f=e.target;if(f.dataset.cfForm==='question'){e.preventDefault();const id=f.dataset.member;try{cfCommit(n=>{(n.cf.questions[id]??=[]).push(CF.answer(n,DATA,id,f.question.value));});render();}catch(err){toast(err.message);}return;}if(f.id==='cf-feedback-form'){e.preventDefault();try{const v=Object.fromEntries(new FormData(f));const t=S.tasks.find(t=>t.id===f.dataset.task);const token=f.dataset.token||(f.dataset.token='SUBMIT-'+crypto.randomUUID());cfCommit(n=>{const report=CF.feedback(n,DATA,t.id,v.response,v.comments,v.respondent,token);n.cf.feedbackConfirmation={task:t.id,by:report.submittedBy};});render();}catch(err){$('#cf-feedback-error').textContent=err.message;}return;}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.cfChange==='sort'){S.cf.filters.sort=el.value;persist();render();}if(el.dataset.cfChange==='change-filter'){S.cf.changeFilter=el.value;persist();render();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-cf]');if(!b)return;const a=b.dataset.cf,id=b.dataset.member,tid=b.dataset.entity;try{switch(a){
 case 'filter':S.cf.filters.quick=b.dataset.value;if(S.active!=='home'||!['dashboard','queue'].includes(S.view)){S.active='home';S.view='dashboard';}persist();render();break;
 case 'action-filter':S.cf.actionFilter=b.dataset.value;persist();render();break;
 case 'waiting':S.active='home';S.view='tasks';S.cf.actionFilter='waiting';persist();render();cfPush();break;
 case 'section':section(id,b.dataset.section);break;
 case 'priority':showOverride(id);break;
 case 'notify-open':closeModal();openPatient(id);break;
 case 'next':{const n=CF.nextAction(S,DATA,id);openPatient(id);if(n.target==='action')cfActionModal(n.entity);else{S.patientSection[id]=n.target==='calls'?'calls':n.target==='medications'?'medications':'outcomes';render();}break;}
 case 'ask-example':cfCommit(n=>{(n.cf.questions[id]??=[]).push(CF.answer(n,DATA,id,b.dataset.question));});render();break;
 case 'evidence':cfEvidence(id,b.dataset.record);break;
 case 'prepare-call':cfPrepare(id);break;
 case 'clock':cfClock(id);break;
 case 'clock-preset':{const time=b.dataset.value;$('#cf-clock-form').time.value=CF.today(S)+'T'+time;break;}
 case 'save-clock':{const f=$('#cf-clock-form');try{cfCommit(n=>CF.setClock(n,f.time.value+':00-05:00'));closeModal();render();if(id)cfPrepare(id);}catch(err){$('#cf-clock-error').textContent=err.message;}break;}
 case 'start-call':{const f=$('#cf-call-form'),v=Object.fromEntries(new FormData(f));try{const call=cfCommit(n=>{n.cf.consents[id]={ai:!!v.ai,channel:!!v.channel,identity:!!v.identity,optOut:!!v.optOut,caregiver:!!v.caregiver,source:'RN-reviewed fictional AI outreach readiness',reviewedAt:CF.now(n)};return CF.startCall(n,DATA,id,v.branch,v.language);});closeModal();openPatient(id);S.patientSection[id]='calls';S.cf.selectedCall=call.id;persist();render();}catch(err){$('#cf-call-error').textContent=err.message;}break;}
 case 'open-call':openPatient(id);S.patientSection[id]='calls';S.cf.selectedCall=tid;render();break;
 case 'call-step':cfCommit(n=>CF.stepCall(n,DATA,tid));render();break;
 case 'call-pause':cfCommit(n=>{const c=n.cf.calls.find(c=>c.id===tid&&c.member===id);if(!c)throw Error('Call context mismatch.');c.status=c.status==='Paused'?'Running':'Paused';});render();break;
 case 'call-end':cfCommit(n=>CF.finishCall(n,DATA,tid,true));render();break;
 case 'call-human':cfCommit(n=>{const c=n.cf.calls.find(c=>c.id===tid&&c.member===id);if(!c)throw Error('Call context mismatch.');CF.finishCall(n,DATA,tid,true);c.escalation='Human assistance requested by RN; review callback context';c.status='Escalated';});render();break;
 case 'review-call':cfReviewCall(id,tid);break;
 case 'approve-call':{const f=$('#cf-review-form'),v=Object.fromEntries(new FormData(f));try{cfCommit(n=>CF.approve(n,DATA,'PROPOSAL-'+tid,{reviewed:!!v.reviewed,task:!!v.task,note:!!v.note,action:v.action}));closeModal();S.dockOpen=true;openPatient(id);S.patientSection[id]='calls';persist();render();toast('Selected updates approved; note remains a draft.');}catch(err){$('#cf-review-error').textContent=err.message;}break;}
 case 'reject-call':cfCommit(n=>{const c=n.cf.calls.find(c=>c.id===tid&&c.member===id);c.reviewState='Reviewed';const p=n.cf.proposals.find(p=>p.callId===tid);if(p)p.status='Rejected';CF.log(n,'RN action',id,'AI proposal rejected','No proposed facts or tasks applied',tid);});closeModal();render();break;
 case 'action':cfActionModal(tid);break;
 case 'save-action':{const f=$('#cf-action-form'),v=Object.fromEntries(new FormData(f));v.dependencies=new FormData(f).getAll('dependencies');try{cfCommit(n=>CF.updateTask(n,DATA,tid,v));closeModal();render();toast('Action, evidence and history updated.');}catch(err){$('#cf-action-error').textContent=err.message;}break;}
 case 'escalate':cfCommit(n=>{const t=n.tasks.find(t=>t.id===tid);t.priority='P1';t.nextReviewAt=CF.today(n);CF.log(n,'Coordination',t.member,'Action escalated for review',t.title,tid);});closeModal();render();break;
 case 'substitute':closeModal();showTask(id);$('#task-form').title.value='Alternative support for: '+S.tasks.find(t=>t.id===tid).title;break;
 case 'feedback-open':closeModal();S.cf.feedbackTask=tid;S.cf.feedbackConfirmation=null;S.active='home';S.view='feedback';persist();render();cfPush();break;
 case 'feedback-another':S.cf.feedbackConfirmation=null;render();break;
 case 'return-rn':S.dockOpen=false;S.cf.feedbackConfirmation=null;if(id&&patient(id)){openPatient(id);S.patientSection[id]='outcomes';}else goto('dashboard');render();cfPush();break;
 case 'goal':cfGoalModal(tid);break;
 case 'save-goal':{const v=Object.fromEntries(new FormData($('#cf-goal-form')));cfCommit(n=>CF.goalUpdate(n,DATA,tid,v));closeModal();render();break;}
 case 'new-goal':showModal('Add patient goal',pname(patient(id)),`<form id="cf-new-goal"><label>Patient-stated goal<textarea name="statement"></textarea></label><label>Agreed success criteria<textarea name="criteria"></textarea></label><label class="checkline"><input type="checkbox" name="confirmed"> Confirmed with member or authorized caregiver</label></form>`,`${btn('close-modal','Cancel')}${cfButton('save-new-goal','Add goal',id,'','primary')}`);break;
 case 'save-new-goal':{const f=$('#cf-new-goal'),v=Object.fromEntries(new FormData(f));if(!v.statement?.trim()||!v.criteria?.trim()||!v.confirmed)throw Error('Record the patient goal and success criteria, and confirm agreement.');cfCommit(n=>{const gid='GOAL-NEW-'+(++n.cf.sequence);n.cf.goals.push({id:gid,member:id,caseId:CF.caseId(id),statement:v.statement,criteria:v.criteria,status:'Not started',evidence:[],history:[],barrier:'Not yet established'});CF.log(n,'RN action',id,'Patient goal agreed',v.statement,gid);});closeModal();render();break;}
 case 'inject':cfCommit(n=>CF.inject(n,DATA,id));render();toast('Labeled synthetic update received. Original source rows unchanged.');break;
 case 'export-v2':exportBlob('CareFlow_v2_Workspace_Backup.json',JSON.stringify({format:'carethread-backup-v1',schemaVersion:2,synthetic:true,savedAt:new Date().toISOString(),state:S},null,2));break;
 case 'manual-limits':showModal('Demonstration boundaries','Useful workflows, explicit limits.',`<p>All patient facts are fictional. Q&A is deterministic and source-grounded. Calls and external coordination are simulations. Patient feedback shares this browser’s local state; separate devices do not synchronize. No API key, real phone call, diagnosis, prescription or insurance decision is used.</p><p>Demo-role checks are not authentication. Local audit data is not an immutable production compliance system.</p>`,btn('close-modal','Understood'));break;
 case 'showcase':cfShowcaseStart();break;
 case 'story-exit':cfStoryStop();break;
 case 'story-next':cfStoryNext();break;
 case 'story-do':cfStoryNext();break;
 }}catch(err){if($('#form-error'))formError(err.message);else toast(err.message);}});
// Capture invalid consequential legacy transitions before their preserved handlers run.
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,a=b.dataset.action;try{
 if(a==='save-lifecycle'&&$('#life-form')?.status.value==='Closed'){const f=$('#life-form');if(f.reason.value!=='Transferred'&&(CF.pendingCalls(S,id).length||CF.negative(S,id).length||f.reason.value==='Goals met'&&S.cf.goals.some(g=>g.member===id&&g.status!=='Achieved')))throw Error('Review unresolved feedback, AI escalations and patient goals before closing, or document an accepted handoff.');}
 if(a==='save-override'&&$('#override-form')?.tier.value==='P0'&&!/protocol|urgent|escalat/i.test($('#override-form').reason.value))throw Error('P0 needs clinician-confirmed urgency and an approved protocol/escalation reference. No seed member has a confirmed emergency.');
 if(a==='reset-data'){cfStorageBlocked=false;$('#cf-story')?.remove();cfShowcase=null;}
}catch(err){e.preventDefault();e.stopImmediatePropagation();formError(err.message);}},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='sample-task'){const f=$('#task-form');if(f?.evidenceDate){f.evidenceDate.value=CF.today(S);f.evidenceSource.value='Clearly simulated service/team confirmation';}}if(b.dataset.action==='confirm-sign'){const n=S.notes[0];if(n&&!n.simulatedAt){n.simulatedAt=CF.now(S);n.sourceReferences=S.cf.calls.filter(c=>c.member===n.member&&c.reviewState==='Reviewed').at(-1)?.turns.map(t=>t.id)||[];persist();}}if(b.dataset.action==='save-plan'){for(const g of S.cf.goals){if(g.id==='GOAL-'+g.member)g.statement=S.cases[g.member].goal;}}if(b.dataset.action==='clear-filters'){S.cf.filters.quick='all';render();}});
// Validate old and new backup imports before replacing any current records.
document.addEventListener('change',async e=>{if(e.target.id!=='backup-file')return;e.stopImmediatePropagation();const file=e.target.files[0];if(!file)return;try{const b=JSON.parse(await file.text());if(b.synthetic!==true||!['carethread-backup-v1','careflow-backup-v2'].includes(b.format))throw Error('Choose a CareFlow synthetic workspace backup.');const restored=CF.migrate(b.state,DATA);window.pendingBackup=restored;showModal('Restore reviewed backup?','Current work is retained until you confirm. Export a current backup first.',`<p>${restored.tasks.length} actions, ${restored.notes.length} signed notes, ${restored.cf.feedback.length} feedback reports. Legacy versions are migrated without deleting source facts.</p>`,`${btn('close-modal','Cancel')}${cfButton('restore-v2','Restore this backup','','','primary')}`);}catch(err){toast('Backup not restored: '+err.message);}e.target.value='';},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-cf="restore-v2"]')&&window.pendingBackup){S=CF.migrate(window.pendingBackup,DATA);window.pendingBackup=null;cfStorageBlocked=false;persist();closeModal();render();toast('Workspace restored with member links validated.');}});
const cfOriginalRenderModal=renderModal,cfOriginalCloseModal=closeModal;
renderModal=function(){cfOriginalRenderModal();if(cfShowcase)cfShowcaseOverlay();};
closeModal=function(){cfOriginalCloseModal();if(cfShowcase)cfShowcaseOverlay();};
var cfIntroDismissed=false;try{cfIntroDismissed=sessionStorage.getItem('careflow-journey-intro-dismissed')==='yes';}catch{}
function cfDismissIntro(){cfIntroDismissed=true;try{sessionStorage.setItem('careflow-journey-intro-dismissed','yes');}catch{}$('#cf-intro')?.remove();$('.journey-top')?.classList.remove('cf-launcher-highlight');}
function cfIntro(){
 if(typeof cfIntroDismissed==='undefined')return;const launcher=$('.journey-top');if(cfIntroDismissed||tour||cfShowcase||modal||drawer||!launcher||S.view==='feedback'){$('#cf-intro')?.remove();launcher?.classList.remove('cf-launcher-highlight');return;}
 launcher.classList.add('cf-launcher-highlight');let host=$('#cf-intro');if(!host){host=document.createElement('div');host.id='cf-intro';host.innerHTML=`<aside class="cf-guide-pop cf-intro-pop" role="region" aria-label="Tutorial introduction"><span class="eyebrow">New to CareFlow?</span><h3>Start with a guided journey.</h3><p>Click the highlighted Play a journey button. We’ll guide you through the workspace, one action at a time.</p><button class="btn quiet small" data-cf="dismiss-intro">Dismiss and explore on my own</button></aside>`;document.body.append(host);}placeGuide(host,launcher);
}
document.addEventListener('click',e=>{if(e.target.closest('[data-cf="dismiss-intro"],[data-action="journeys"],[data-view="journeys"],[data-action="start-journey"],[data-cf="showcase"]'))cfDismissIntro();},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(cfShowcase&&!modal&&!drawer)cfStoryStop();else if(!tour&&!cfShowcase)cfDismissIntro();}});
let cfGuideFrame=0;function cfGuideReposition(){cancelAnimationFrame(cfGuideFrame);cfGuideFrame=requestAnimationFrame(()=>{if(cfShowcase)cfShowcaseOverlay();if(!cfIntroDismissed)cfIntro();});}
document.addEventListener('scroll',cfGuideReposition,true);window.addEventListener('resize',cfGuideReposition);
document.addEventListener('click',cfStoryObserve);document.addEventListener('submit',cfStoryObserve);
// Start on Command Center, including downloaded HTML and a previously saved journeys view.
// An explicit patient-feedback link still opens its intervention. In-session navigation is retained.
if(!location.hash.startsWith('#feedback/')){S.active='home';S.view='dashboard';history.replaceState(null,'','#home/dashboard');}
render();cfRoute();

